root=Path(__file__).resolve().parent;p=argparse.ArgumentParser();p.add_argument('--epochs',type=int,default=100);a=p.parse_args();out=root/'models_moe';out.mkdir(exist_ok=True);tf.config.threading.set_intra_op_parallelism_threads(2);tf.config.threading.set_inter_op_parallelism_threads(1);tf.keras.utils.set_random_seed(20261029);manifest={'train':[],'val':[],'excluded':[],'test_used':False,'earlier_data_used':False}
def load(split):
 hs=[];fs=[];ys=[];weights=[]
 for path in sorted((root/'data').glob(split+'_*.json')):
  meta=json.loads(path.read_text())
  if not meta['success']:manifest['excluded'].append({'path':str(path.relative_to(root)),'reason':'teacher episode did not complete forward without collision'});continue
  z=np.load(path.with_suffix('.npz'));h=z['scan'];f=np.load(root/'prepared'/(path.stem+'.npz'))['features'];mask=z['mask'];y=np.c_[z['target'],mask,np.load(root/'prepared_moe'/(path.stem+'.npz'))['side']];valid=mask[:,0]>.5;h=h[valid];f=f[valid];y=y[valid];objects=f[:,34:66].reshape(-1,4,8);near=np.any((objects[:,:,3]>.5)&(objects[:,:,7]<.65),axis=1);weight=np.where(near,3.0,1.0)*np.where(abs(y[:,0])>.1,1.5,1.)
