mh=h[:,:,::-1,:].copy();mf=f.copy();mf[:,:16]=(f[:,:16].reshape(-1,8,2)*[1,-1]).reshape(-1,16);mf[:,16:32]=f[:,16:32].reshape(-1,8,2)[:,:,::-1].reshape(-1,16);mf[:,33]*=-1;mf[:,66]*=-1;mf[:,84]*=-1;mf[:,87:94:2]*=-1;ob=f[:,34:66].reshape(-1,4,8).copy();ob[:,:,1]*=-1;ob[:,:,6]*=-1;ob[:,:,[4,5]]=ob[:,:,[5,4]];mf[:,34:66]=ob.reshape(-1,32);mf[:,68:76]=(f[:,68:76].reshape(-1,4,2)*[1,-1]).reshape(-1,8);mf[:,76:84]=f[:,76:84].reshape(-1,4,2)[:,:,::-1].reshape(-1,8);my=y.copy();my[:,0:12:2]*=-1;my[:,19:21]=y[:,19:21][:,::-1];h=np.r_[h,mh];f=np.r_[f,mf];y=np.r_[y,my];w=np.r_[w,w];(root/'results/dataset_manifest_moe.json').write_text(json.dumps(manifest,indent=2))
