for i,(filters,kernel,stride) in enumerate([(16,9,4),(24,5,4),(32,3,2)]):x=tf.keras.layers.TimeDistributed(tf.keras.layers.Conv1D(filters,kernel,strides=stride,padding='same',activation='relu'),name=f'lidar_conv_{i}')(x)
