for mode in ['clear','left','right']:
 branch=tf.keras.layers.Dense(48,activation='relu',name=mode+'_branch')(x);steering=tf.keras.layers.Dense(6,activation='tanh',kernel_initializer='zeros',name=mode+'_steering')(branch);speed=tf.keras.layers.Dense(6,activation='sigmoid',bias_initializer=tf.keras.initializers.Constant(.25),name=mode+'_speed')(branch);action=tf.keras.layers.Concatenate(axis=-1)([tf.keras.layers.Reshape((6,1))(steering),tf.keras.layers.Reshape((6,1))(speed)]);heads.append(tf.keras.layers.Flatten()(action))
