 truth=tf.reshape(y[:,:12],(-1,6,2));branches=tf.reshape(p[:,:36],(-1,3,6,2));prediction=tf.einsum('bi,bijk->bjk',y[:,18:21],branches);d=tf.abs(truth-prediction);threshold=tf.constant([.04,.08]);huber=tf.where(d<threshold,.5*d*d,threshold*d-.5*threshold*threshold);mask=y[:,12:18];time_weights=tf.constant([1.,.6,.45,.35,.25,.2]);weights=tf.constant([5.,2.]);regression=tf.reduce_sum(tf.reduce_sum(huber*weights,axis=-1)*mask*time_weights,axis=-1);classification=-tf.reduce_sum(y[:,18:21]*tf.math.log(tf.clip_by_value(p[:,36:39],1e-6,1.)),axis=-1)*y[:,21];return regression+.035*classification
